def decode(encoded: str, original: str, message: str) -> str:
    """
    Decodes an encrypted message using a cipher derived from a known encoded-original pair.
    Builds a mapping from encoded letters to original letters. If contradictions are found
    or not all 26 letters are represented, returns "Failed". Otherwise decodes the message.
    """
    # Basic input validation
    if not isinstance(encoded, str) or not isinstance(original, str) or not isinstance(message, str):
        return "Failed"

    # The encoded and original strings must be of equal length
    if len(encoded) != len(original):
        return "Failed"

    mapping = {}           # encoded char -> original char
    for e_char, o_char in zip(encoded, original):
        # ignore non-letter characters if any
        if not e_char.isalpha() or not o_char.isalpha():
            continue
        e_char = e_char.upper()
        o_char = o_char.upper()
        if e_char in mapping:
            if mapping[e_char] != o_char:
                return "Failed"  # contradiction
        else:
            mapping[e_char] = o_char

    # Ensure mapping covers all 26 English letters
    if len(mapping) < 26:
        return "Failed"

    # Decode the message
    result_chars = []
    for ch in message:
        # Only letters are decoded; treat others unchanged
        if ch.isalpha():
            up = ch.upper()
            if up not in mapping:
                return "Failed"
            # Preserve case of original message character
            decoded_char = mapping[up]
            result_chars.append(decoded_char.lower() if ch.islower() else decoded_char)
        else:
            result_chars.append(ch)

    return "".join(result_chars)

def count_coprime_pairs(x0: int, y0: int) -> int:
    """Count pairs (P, Q) of positive integers with GCD = x0 and LCM = y0."""
    # Validate inputs
    if x0 <= 0 or y0 <= 0:
        return 0
    if y0 % x0 != 0 or y0 < x0:
        return 0

    n = y0 // x0

    def _gcd(a: int, b: int) -> int:
        while b:
            a, b = b, a % b
        return a

    count = 0
    i = 1
    while i * i <= n:
        if n % i == 0:
            a = i
            b = n // i
            if _gcd(a, b) == 1:
                if a == b:
                    count += 1
                else:
                    count += 2
        i += 1
    return count

def generate_numbers(n, rules) -> int:
    """
    Generate all unique numbers from the given number by applying transformation rules.
    Each rule allows a single digit to be transformed into another. The function
    returns the count of unique numbers that can be generated from the original
    number, including the number itself.

    Args:
        n (int): The original integer number to transform.
        rules (list of tuples): A list of transformation rules, where each
            rule is represented as a tuple (x, y) indicating that digit x can
            be transformed into y.

    Returns:
        int: The total count of unique numbers that can be generated.
    """
    # Basic validation
    if not isinstance(n, int):
        raise TypeError("n must be an integer")
    if not isinstance(rules, list):
        raise TypeError("rules must be a list of tuples")
    for rule in rules:
        if not isinstance(rule, tuple) or len(rule) != 2:
            raise ValueError("each rule must be a tuple of two elements")
        if not (isinstance(rule[0], int) and isinstance(rule[1], int)):
            raise ValueError("rule elements must be integers")

    # Convert number to string for easier digit manipulation
    original = str(n)
    visited = set([original])
    queue = [original]

    # Preprocess rules into a dictionary mapping source digit to list of targets
    rule_map = {}
    for src, tgt in rules:
        if not 0 <= src <= 9 or not 0 <= tgt <= 9:
            continue  # ignore rules with invalid digits
        rule_map.setdefault(str(src), []).append(str(tgt))

    while queue:
        current = queue.pop(0)
        for i, ch in enumerate(current):
            if ch in rule_map:
                for tgt in rule_map[ch]:
                    new_num = current[:i] + tgt + current[i+1:]
                    if new_num not in visited:
                        visited.add(new_num)
                        queue.append(new_num)

    return len(visited)

def minimum_students_to_leave(heights):
    """
    Calculate the minimum number of students that need to leave to form a choir formation.
    A choir formation is defined such that for some position 'i', the heights of students
    increase from the start to 'i' and decrease from 'i' to the end of the formation.

    Args:
        heights (List[int]): A list of student heights.

    Returns:
        int: The minimum number of students that need to leave.
    """
    # Validate input
    if not isinstance(heights, list):
        raise TypeError("heights must be a list")
    for h in heights:
        if not isinstance(h, int):
            raise TypeError("all elements of heights must be integers")
    n = len(heights)
    if n <= 1:
        return 0  # No one needs to leave if 0 or 1 student

    # Compute LIS ending at each index
    lis = [1] * n
    for i in range(n):
        for j in range(i):
            if heights[j] < heights[i] and lis[j] + 1 > lis[i]:
                lis[i] = lis[j] + 1

    # Compute LDS starting at each index
    lds = [1] * n
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if heights[j] < heights[i] and lds[j] + 1 > lds[i]:
                lds[i] = lds[j] + 1

    # Find maximum bitonic length
    max_bitonic = 0
    for i in range(n):
        current = lis[i] + lds[i] - 1  # peak counted twice
        if current > max_bitonic:
            max_bitonic = current

    # Minimum removals = total - maximum bitonic subsequence length
    return n - max_bitonic

def sort_students(student_scores):
    """
    Sorts a list of students based on their scores. The students are sorted primarily by their total score (descending),
    then by their Chinese score (descending), and finally by their student number (ascending) in case of a tie.

    Args:
        student_scores (list): A list of tuples, where each tuple consists of (student_number, total_score, Chinese_score).

    Returns:
        list: A list of tuples sorted according to the above rules.
    """
    if not isinstance(student_scores, list):
        raise TypeError("student_scores must be a list")
    # Validate each item
    for idx, s in enumerate(student_scores):
        if not isinstance(s, tuple) or len(s) != 3:
            raise ValueError(f"Element at index {idx} is not a 3-tuple: {s}")
        stu_num, total, chn = s
        if not (isinstance(stu_num, (int, float)) and isinstance(total, (int, float)) and isinstance(chn, (int, float))):
            raise ValueError(f"Tuple at index {idx} must contain numeric values: {s}")
    try:
        sorted_list = sorted(
            student_scores,
            key=lambda x: (-x[1], -x[2], x[0])  # total score desc, Chinese score desc, student number asc
        )
    except Exception as exc:
        raise RuntimeError(f"Failed to sort student scores: {exc}") from exc
    return sorted_list
